  let(:imp_context) do
    Timekeeping::WriteContext.new(company: imp_company, actor: imp_admin, actor_kind: "import", request_id: "req-import-1")
  end

  # "A generation change or a handoff raises `Timekeeping::Gateway::StaleGeneration` or `OwnershipMoving`."
  it "an import refused for a stale generation reports one event naming the import actor kind and nothing else" do
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(generation: 3)
    events = []
    subscriber = Object.new
    subscriber.define_singleton_method(:emit) do |event|
      events << event if event[:name] == "Timekeeping::EntryWriteRefused"
    end
    Rails.event.subscribe(subscriber)
    begin
      expect do
        described_class.new(context: imp_context).import(
          user: imp_admin, project: imp_project,
          attributes: { duration: 30, work_date: Date.current, note: "harvest", bill_status: "billed",
                        source: "import", source_metadata: { tool: "harvest" } },
          idempotency_key: "4c3f6c1e-0d6a-5b1e-9a0e-1b9e8f3d2a41", expected_generation: 2
        )
      end.to raise_error(Timekeeping::Gateway::StaleGeneration)
    ensure
      Rails.event.unsubscribe(subscriber)
    end

    expect(TimesheetEntry.count).to eq(0)
    expect(events.size).to eq(1)
    # The payload carries only who and where, never the retry key or a token.
    expect(events.first[:payload].to_h[:data]).to eq(
      reason: "stale_generation", company_id: imp_company.id, request_id: "req-import-1", actor_kind: "import"
    )
  end
end

RSpec.describe Timekeeping::Gateway do
  let(:fb_company) { create(:company) }
  let(:fb_admin) do
    create(:user, current_workspace_id: fb_company.id).tap do |user|
      create(:employment, company: fb_company, user:)
      user.add_role :admin, fb_company
    end
  end
  let(:fb_project) { create(:project, billable: true, client: create(:client, company: fb_company)) }
  let(:fb_base_url) { "http://timekeeping.test" }
  let(:fb_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  # "Forwarded, it is one create with `bill_status: "billed"`."
  it "a forwarded billed import is one create carrying billed, the import source and the given Idempotency-Key" do
